+    display: flex;
+    gap: 0.5rem;
+    padding: 0.75rem 1rem;
+    border-top: 1px solid #202225;
+    background-color: #36393f;
+}
+
+.message-input textarea {
+    flex: 1;
+    resize: none;
+    border: none;
+    border-radius: 8px;
+    background-color: #40444b;
+    color: #dcddde;
+    padding: 0.6rem 0.75rem;
+    font-size: 0.9rem;
+    font-family: inherit;
+}
+
+.message-input textarea::placeholder {
+    color: #72767d;
+}
+
+.message-input textarea:focus {
+    outline: none;
+}
+
+.send-button {
+    background-color: #5865f2;
+    color: #ffffff;
+    border: none;
+    border-radius: 8px;
+    padding: 0.6rem 1.2rem;
+    font-weight: 600;
+    cursor: pointer;
+    font-size: 0.85rem;
+}
+
+.send-button:hover:not(:disabled) {
+    background-color: #4752c4;
+}
+
+.send-button:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread Panel */
+.thread-panel {
+    width: 25%;
+    min-width: 250px;
+    background-color: #2f3136;
+    color: #dcddde;
+    display: flex;
+    flex-direction: column;
+    border-left: 1px solid #202225;
+}
+
+.thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #202225;
+}
+
+.thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #ffffff;
+}
+
+.close-btn {
+    background: none;
+    border: none;
+    color: #b9bbbe;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 0.2rem 0.5rem;
+    border-radius: 3px;
+}
+
+.close-btn:hover {
+    background-color: #4f545c;
+    color: #ffffff;
+}
+
+.thread-root-message {
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #202225;
+    background-color: #32353b;
+}
+
+.thread-root-message .message-author {
+    font-size: 0.85rem;
+}
+
+.thread-root-message .message-content {
+    font-size: 0.85rem;
+    margin-top: 0.25rem;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 0.75rem 1rem;
+}
+
+.thread-reply {
+    margin-bottom: 0.75rem;
+    padding-bottom: 0.75rem;
+    border-bottom: 1px solid #40444b;
+}
+
+.thread-reply:last-child {
+    border-bottom: none;
+}
+
+.loading-indicator {
+    text-align: center;
+    padding: 0.5rem;
+    color: #8e9297;
+    font-size: 0.8rem;
+}
+

